// docs/machines.md, drawn from the machines' own rules: the catalog's manifests
// (convex/machines.ts), which the runtime runs too, so the pictures can't drift from
// the code. scripts/diagrams.ts writes it, and convex/loreMachines.test.ts checks it.
import { linkedDiagram, stateDiagram } from "@convex-dev/state-machines";
import { machines as catalog } from "../convex/machines";

const fence = (code: string) => ["```mermaid", code, "```"].join("\n");

export function machineDiagrams() {
  const machines = catalog.manifests;
  return [
    "# State machines",
    "",
    "Generated by `npm run diagrams` from the machines' rules in `convex/loreMachines.ts`. Don't edit by hand: `npm test` fails when it's out of date.",
    "",
    "Each arrow is a transition or a link in the rules. Under each state are its own data fields (`?` if optional). `[*] -->` is how a row is born and `--> [*]` a final state. `(server)` events come from Walkies' own code, `from <machine>` from the other machine, and `after`/`at` from a timer. A list is tried in order: `[1. guard]`, then the next, and `[else]` last. What an effect writes, and which rows a link finds, are in the code.",
    "",
    "## Both machines, and the links between them",
    "",
    fence(linkedDiagram(machines)),
    "",
    ...machines.flatMap((machine) => [`## \`${machine.name}\`, on \`${machine.table}.${machine.field}\``, "", fence(stateDiagram(machine, machines)), ""]),
  ].join("\n");
}
